"""Offline display of solved evidence; no engineering model in JavaScript."""
import json
from pathlib import Path
from .contracts import EngineeringFigureSpec, FigureAvailability, FigureMetadata, SeriesSpec


def render_comparison_html(report, path):
    payload=json.dumps(report,allow_nan=False,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(HTML.replace('__REPORT_JSON__',payload))
    return path


def render_comparison_figures(report,directory):
    from .matplotlib_renderer import render_engineering_figure
    output=[]
    for metric in ('rack_m','front_heading_split_rad'):
        title,unit,_=report['metric_definitions'][metric]
        series=[];missing=[]
        for candidate in report['plan']['candidates']:
            cells=sorted([c for c in report['cells'] if c['candidate_id']==candidate['id'] and c['assumption_id']=='nominal'],key=lambda c:c['case']['curvature_per_m'])
            if len(cells)!=len(report['plan']['cases']) or any(not c['result']['ok'] or c['metrics'] is None for c in cells):
                missing.append(candidate['id']);continue
            series.append(SeriesSpec(candidate['id'],tuple(c['case']['curvature_per_m'] for c in cells),tuple(c['metrics'][metric] for c in cells)))
        metadata=FigureMetadata('ANALYTICAL-'+metric.upper().replace('_','-'),title+' across nominal cases',
            'Signed curvature','1/m',title,unit,'MOD-VEH-0009',report['plan']['plan_id'],
            'uncorrelated_development_evidence_only',state_ids=tuple(s['id'] for s in report['plan']['cases']),
            source_ids=(report['plan_fingerprint'],),notes=('No design ranking; provisional source configuration.',))
        spec=(EngineeringFigureSpec(metadata,availability=FigureAvailability.UNAVAILABLE,
            unavailable_reason='Incomplete nominal solved coverage: '+', '.join(missing)) if missing
            else EngineeringFigureSpec(metadata,tuple(series)))
        output.extend(render_engineering_figure(spec,Path(directory)/metric))
    return tuple(output)


HTML=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Suspension · Analytical comparisons</title>
<style>
:root{font-family:system-ui,sans-serif;background:#10161f;color:#e5eaf0;color-scheme:dark}*{box-sizing:border-box}body{margin:0}main{max-width:1380px;margin:auto;padding:32px}header{display:flex;justify-content:space-between;gap:24px;align-items:start}header>div{min-width:0}h1{font-size:30px;margin:8px 0 12px;letter-spacing:-.7px}h2{font-size:18px;margin:0 0 16px}p{line-height:1.6;color:#afbed0}.eyebrow{font-size:12px;letter-spacing:2px;text-transform:uppercase;color:#79dfc4}.badge{display:inline-block;border:1px solid #34584e;border-radius:20px;padding:5px 11px;color:#8ce8c9;font-size:12px}.scope{background:#1b2836;border-left:3px solid #79b8f2;padding:14px 18px;margin:22px 0;font-size:14px;line-height:1.6}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:22px 0}.card,.panel{min-width:0;background:#17212e;border:1px solid #2d3b4c;border-radius:10px;padding:20px}.number{font-size:28px;font-weight:600;margin:10px 0 5px}.muted{font-size:13px;color:#9cacc0}.controls{display:flex;gap:16px;flex-wrap:wrap;align-items:end;margin-bottom:20px}label{display:flex;flex-direction:column;gap:7px;font-size:13px;color:#bdcadd;max-width:100%}select,button,.file{max-width:100%;padding:9px 12px;background:#202e3f;border:1px solid #405269;border-radius:6px;color:#e5eaf0;font:inherit}button,.file{cursor:pointer}.file input{display:none}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin:18px 0}.table-wrap{max-width:100%;overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:13px}th,td{padding:12px 10px;text-align:left;border-bottom:1px solid #2c3b4d;white-space:nowrap}th{color:#9eb3cb;font-weight:500}.ok{color:#87dfbf}.bad{color:#ffb49c}.note{font-size:12px;line-height:1.6;color:#a6b7cb}.plot{display:block;width:100%;height:310px}.legend{display:flex;gap:18px;flex-wrap:wrap;font-size:12px}.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:6px}details{margin:20px 0}summary{cursor:pointer;color:#c6d7e9}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px;max-height:400px;overflow:auto}footer{padding:18px 0;color:#9aabc0;font-size:12px;overflow-wrap:anywhere}#error{display:none;background:#542c28;padding:14px;border-radius:6px;margin:15px 0}.config td{white-space:normal;overflow-wrap:anywhere}.config td:first-child{min-width:150px}
@media(max-width:900px){main{padding:18px}.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.grid{grid-template-columns:minmax(0,1fr)}header{flex-direction:column}}@media(max-width:420px){.card,.panel{padding:14px}.number{font-size:23px}.controls{gap:12px}.plot{height:250px}}@media print{body{background:white;color:black}.card,.panel{background:white;border-color:#aaa}.controls{display:none}p,.muted,.note{color:#444}}
</style></head><body><main><header><div><div class="eyebrow">PSSD / Engineering workbench</div><h1>Analytical design comparisons</h1><p id="question"></p></div><div><span class="badge">Development evidence</span><p class="muted">Offline report · solved states</p></div></header>
<div id="error" role="alert"></div><div class="scope">Provisional source configuration. Uncorrelated R25B-to-R20 tire proxy with assumed negative-inclination reflection. Results describe model response; packaging, installed setup and actual steering effort remain unresolved.</div>
<section class="cards" aria-label="Study coverage"><div class="card"><div class="muted">Solved cells</div><div class="number" id="solved"></div><div class="muted" id="failed"></div></div><div class="card"><div class="muted">Reference mass</div><div class="number" id="mass"></div><div class="muted">Driver present · no fuel</div></div><div class="card"><div class="muted">Speed / pressure</div><div class="number" id="speed"></div><div class="muted" id="pressure"></div></div><div class="card"><div class="muted">Comparison scope</div><div class="number" id="coverage"></div><div class="muted">Candidate geometries · no ranking</div></div></section>
<section class="panel"><div class="controls"><label>Operating case<select id="case"></select></label><label>Assumption<select id="assumption"></select></label><label>Response<select id="metric"></select></label><button id="download">Download evidence JSON</button><label class="file">Open report JSON<input type="file" id="load" accept=".json,application/json"></label></div><div class="table-wrap"><table><thead><tr><th>Candidate</th><th>State</th><th id="value-head">Value</th><th>Change from reference</th><th>Force / moment residual</th><th>Iterations</th></tr></thead><tbody id="rows"></tbody></table></div><p class="note" id="case-note"></p></section>
<div class="grid"><section class="panel"><h2>Nominal operating-case response</h2><svg class="plot" id="plot" viewBox="0 0 560 310" role="img" aria-label="Nominal response by signed curvature"></svg><div class="legend" id="legend"></div><p class="note">Lines connect solved cases for readability. No intermediate state is calculated.</p></section><section class="panel"><h2>Candidate effect across assumption stresses</h2><div class="table-wrap"><table><thead><tr><th>Candidate</th><th>Min / max change</th><th>Effect sign</th></tr></thead><tbody id="stability"></tbody></table></div><p class="note" id="threshold"></p><p class="note">Comparison is against the original rack at the same case and assumption. Sign stability covers the declared one-at-a-time stresses; it does not establish a preferred design.</p></section></div>
<section class="panel"><h2>Configuration and assumptions</h2><div class="table-wrap"><table class="config"><thead><tr><th>Item</th><th>Definition</th></tr></thead><tbody id="config"></tbody></table></div><p class="note">Alignment uses the existing zero-offset nominal construction: camber changes the nominal wheel center as well as the wheel plane. Tire gain is an analytical force-law stress, not new measured tire data. No combined stresses or uncertainty probabilities are assigned.</p><details><summary>Source identity and numerical controls</summary><pre id="sources"></pre></details></section><footer id="identity"></footer></main>
<script id="report" type="application/json">__REPORT_JSON__</script><script>
'use strict';let data;const $=id=>document.getElementById(id),colors=['#75dac2','#f4bc7c','#91bafa'];const fmt=x=>x===null||x===undefined?'Unavailable':Number(x).toPrecision(6);
function td(tr,text,cls=''){let n=document.createElement('td');n.textContent=text;n.className=cls;tr.append(n)}function row(body,values){let tr=document.createElement('tr');values.forEach(v=>td(tr,v));body.append(tr)}function option(s,v,label){let o=document.createElement('option');o.value=v;o.textContent=label;s.append(o)}
function validate(d){if(d.schema!=='pssd.analytical-design-workflow.v1'||d.design_ranking_permitted!==false||d.objective_weight!==0||!Array.isArray(d.cells)||!Array.isArray(d.comparisons)||!Array.isArray(d.candidate_effect_stability)||!d.metric_definitions||!d.plan?.cases?.length||!d.plan?.candidates?.length||!d.plan?.assumptions?.length)throw Error('Expected a combined unranked analytical report.');for(let c of d.cells){if(!c.result||!c.case||!d.plan.candidates.some(x=>x.id===c.candidate_id)||!d.plan.cases.some(x=>x.id===c.case_id))throw Error('Invalid report cell.');if(c.result.ok&&(!c.metrics||!Object.values(c.metrics).every(Number.isFinite)))throw Error('Solved cell has invalid metrics.');if(!c.result.ok&&c.metrics!==null)throw Error('Failed cell cannot supply response values.');}}
function install(d){validate(d);data=d;$('case').replaceChildren();d.plan.cases.forEach(s=>option($('case'),s.id,s.id+' · κ '+s.curvature_per_m+' /m'));$('metric').replaceChildren();Object.entries(d.metric_definitions).forEach(([k,v])=>option($('metric'),k,v[0]+' ('+v[1]+')'));$('question').textContent=d.plan.design_question;$('solved').textContent=d.cells.filter(c=>c.result.ok).length+' / '+d.cells.length;$('failed').textContent=d.cells.filter(c=>!c.result.ok).length+' failed cells retained';$('mass').textContent=d.plan.reference.mass_kg.toFixed(3)+' kg';$('speed').textContent=d.plan.reference.speed_mps+' m/s';$('pressure').textContent=d.plan.reference.pressure_pa/1000+' kPa gauge · ARB '+d.plan.reference.front_arb_setting+'/'+d.plan.reference.rear_arb_setting;$('coverage').textContent=d.plan.candidates.length+' candidates';$('config').replaceChildren();row($('config'),['Source role',d.plan.configuration_role.replaceAll('_',' ')]);let base=d.cells.find(c=>c.candidate_id==='reference'&&c.assumption_id==='nominal');for(let axle of ['front','rear']){let f=base?.[axle+'_reference'];if(f)row($('config'),[axle+' source alignment','Toe-out '+(f.static_toe_out_rad*180/Math.PI).toFixed(3)+'°; top-out camber '+(f.static_camber_rad*180/Math.PI).toFixed(3)+'°']);}d.plan.candidates.forEach(c=>row($('config'),[c.id,'Rack body-x offset '+c.rack_longitudinal_offset_m*1000+' mm; center closure preserved by derived tie-rod lengths']));d.plan.assumptions.forEach(a=>row($('config'),[a.id,'Front toe Δ '+a.front_toe_delta_deg+'°; camber Δ '+a.front_camber_delta_deg+'°; lateral force × '+a.lateral_force_gain]));$('sources').textContent=JSON.stringify({plan:d.plan.plan_id,plan_fingerprint:d.plan_fingerprint,solver:d.plan.solver,source_hashes:d.source_hashes},null,2);$('identity').textContent='Plan '+d.plan.plan_id+' · '+d.plan_fingerprint+' · '+d.status;updateAssumptions();}
function updateAssumptions(){let old=$('assumption').value,id=$('case').value;$('assumption').replaceChildren();data.plan.assumptions.filter(a=>data.cells.some(c=>c.case_id===id&&c.assumption_id===a.id)).forEach(a=>option($('assumption'),a.id,a.id));if([...$('assumption').options].some(o=>o.value===old))$('assumption').value=old;render();}
function render(){let state=$('case').value,a=$('assumption').value,m=$('metric').value,def=data.metric_definitions[m];$('value-head').textContent=def[0]+' ('+def[1]+')';$('rows').replaceChildren();for(let candidate of data.plan.candidates){let c=data.cells.find(x=>x.candidate_id===candidate.id&&x.case_id===state&&x.assumption_id===a),cmp=data.comparisons.find(x=>x.candidate_id===candidate.id&&x.case_id===state&&x.assumption_id===a),tr=document.createElement('tr');td(tr,candidate.id);td(tr,c?.result.ok?'Solved':c?.result.failure_code||'Missing',c?.result.ok?'ok':'bad');td(tr,fmt(c?.metrics?.[m]));td(tr,cmp?.comparison_supported?fmt(cmp.delta_from_reference[m]):'Unavailable · '+(cmp?.reason||'missing'));td(tr,c?fmt(c.physical_force_norm_n)+' N / '+fmt(c.physical_moment_norm_nm)+' N·m':'Unavailable');td(tr,c?String(c.result.iterations):'—');$('rows').append(tr);}$('case-note').textContent=data.plan.cases.find(s=>s.id===state).assumption_study?'Nominal and six one-at-a-time stress cases are scheduled here.':'Only the nominal assumption is scheduled at this operating point.';$('stability').replaceChildren();let stability=data.candidate_effect_stability.filter(x=>x.case_id===state&&x.metric===m);if(!stability.length)row($('stability'),['Not scheduled','—','No stress coverage at this case']);stability.forEach(s=>row($('stability'),[s.candidate_id,fmt(s.minimum_effect)+' / '+fmt(s.maximum_effect)+' '+s.unit,s.effect_sign.replaceAll('_',' ')]));$('threshold').textContent='Sign reporting threshold: '+def[2]+' '+def[1]+'. This is a reporting threshold, not a model accuracy interval.';plot(m,def);}
function svg(tag,attrs,text){let n=document.createElementNS('http://www.w3.org/2000/svg',tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));if(text!==undefined)n.textContent=text;return n}
function plot(m,def){let root=$('plot');root.replaceChildren();$('legend').replaceChildren();let groups=data.plan.candidates.map(c=>({id:c.id,cells:data.cells.filter(x=>x.candidate_id===c.id&&x.assumption_id==='nominal').sort((a,b)=>a.case.curvature_per_m-b.case.curvature_per_m)}));if(groups.some(g=>g.cells.length!==data.plan.cases.length||g.cells.some(c=>!c.result.ok||!c.metrics))){root.append(svg('text',{x:25,y:80,fill:'#ffb49c'},'Plot unavailable: incomplete nominal solved coverage.'));return;}let xs=groups.flatMap(g=>g.cells.map(c=>c.case.curvature_per_m)),ys=groups.flatMap(g=>g.cells.map(c=>c.metrics[m])),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),pad=(ymax-ymin)*.12||1e-6;ymin-=pad;ymax+=pad;let X=x=>68+(x-xmin)/(xmax-xmin||1)*465,Y=y=>255-(y-ymin)/(ymax-ymin)*225;for(let i=0;i<5;i++){let v=ymin+(ymax-ymin)*i/4,y=Y(v);root.append(svg('line',{x1:68,x2:533,y1:y,y2:y,stroke:'#304155'}));root.append(svg('text',{x:62,y:y+4,fill:'#a6b7cb','text-anchor':'end','font-size':10},v.toExponential(2)));}[...new Set(xs)].forEach(x=>root.append(svg('text',{x:X(x),y:278,fill:'#a6b7cb','text-anchor':'middle','font-size':11},String(x))));root.append(svg('text',{x:300,y:304,fill:'#a6b7cb','text-anchor':'middle','font-size':11},'Signed curvature (1/m)'));root.append(svg('text',{x:68,y:16,fill:'#a6b7cb','font-size':11},def[0]+' ('+def[1]+')'));groups.forEach((g,i)=>{let color=colors[i%colors.length];root.append(svg('polyline',{points:g.cells.map(c=>X(c.case.curvature_per_m)+','+Y(c.metrics[m])).join(' '),fill:'none',stroke:color,'stroke-width':2}));g.cells.forEach(c=>{let p=svg('circle',{cx:X(c.case.curvature_per_m),cy:Y(c.metrics[m]),r:4,fill:color});p.append(svg('title',{},g.id+' · '+c.case_id+' · '+fmt(c.metrics[m])));root.append(p)});let span=document.createElement('span'),dot=document.createElement('i');dot.className='dot';dot.style.background=color;span.append(dot,document.createTextNode(g.id));$('legend').append(span)});}
$('case').addEventListener('change',updateAssumptions);$('assumption').addEventListener('change',render);$('metric').addEventListener('change',render);$('download').onclick=()=>{let url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='analytical-comparison.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('load').onchange=async e=>{try{install(JSON.parse(await e.target.files[0].text()));$('error').style.display='none'}catch(err){$('error').textContent='Could not open report: '+err.message;$('error').style.display='block'}};install(JSON.parse($('report').textContent));
</script></body></html>'''
